/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, gt, isNull, like, ne } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { InvalidSlugError, SLUG_MAX_LENGTH, uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import {
  getDb,
  members,
  organizations,
  organizationSlugRetirements,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";
import type { Db } from "@/server/db";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** A hold expires at the boundary, so only retirements after this count. */
function slugHoldCutoff(now: Date): string {
  return toIsoTimestamp(new Date(now.getTime() - ORG_SLUG_HOLD_DAYS * MS_PER_DAY));
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const db = getDb();
  const row = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retired = db
    .select({ org: organizations })
    .from(organizationSlugRetirements)
    .innerJoin(organizations, eq(organizations.id, organizationSlugRetirements.orgId))
    .where(
      and(
        eq(organizationSlugRetirements.slug, slug),
        gt(organizationSlugRetirements.retiredAt, slugHoldCutoff(new Date())),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return retired ? toOrganization(retired.org) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Derives and claims a slug in the same transaction, including retired slugs
 * in the taken set so creation cannot steal a URL whose hold is still active.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  return getDb().transaction((tx) => {
    const now = new Date();
    const slug = uniqueSlug(input.slug, takenOrgSlugs(tx, input.slug, now));
    const stamp = toIsoTimestamp(now);

    tx.delete(organizationSlugRetirements)
      .where(eq(organizationSlugRetirements.slug, slug))
      .run();

    const row = tx
      .insert(organizations)
      .values({
        id: newId(),
        name: input.name,
        slug,
        ownerId,
        plan: input.plan,
        logoUrl: null,
        trialEndsAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    return toOrganization(row);
  }, { behavior: "immediate" });
}

/** Settings and profile patch; URL changes go through `renameOrgSlug`. */
export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

/** Checks availability, retires the old URL and claims the new URL atomically. */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<{ organization: Organization; from: string } | null> {
  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) return null;
    if (current.slug === slug) {
      return { organization: toOrganization(current), from: current.slug };
    }

    const now = new Date();
    const taken = tx
      .select({ id: organizations.id })
      .from(organizations)
      .where(eq(organizations.slug, slug))
      .get();
    const held = tx
      .select({ slug: organizationSlugRetirements.slug })
      .from(organizationSlugRetirements)
      .where(
        and(
          eq(organizationSlugRetirements.slug, slug),
          ne(organizationSlugRetirements.orgId, orgId),
          gt(organizationSlugRetirements.retiredAt, slugHoldCutoff(now)),
        ),
      )
      .get();
    if (taken || held) throw new InvalidSlugError(slug, "is already taken or held");

    // Reclaiming a retired URL ends its retirement. Any other row here has
    // already expired, and can likewise be removed before claiming the slug.
    tx.delete(organizationSlugRetirements)
      .where(eq(organizationSlugRetirements.slug, slug))
      .run();

    const stamp = toIsoTimestamp(now);
    tx.insert(organizationSlugRetirements)
      .values({ slug: current.slug, orgId, retiredAt: stamp })
      .onConflictDoUpdate({
        target: organizationSlugRetirements.slug,
        set: { orgId, retiredAt: stamp },
      })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    return { organization: toOrganization(row), from: current.slug };
  }, { behavior: "immediate" });
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()` with current slugs and unexpired retirements. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  return takenOrgSlugs(getDb(), prefix, new Date());
}

function takenOrgSlugs(
  db: Pick<Db, "select">,
  prefix: string,
  now: Date,
): readonly string[] {
  // uniqueSlug truncates long bases before adding a suffix; include those
  // candidates in the prefix scan as well as the unsuffixed slug.
  const pattern = `${prefix.slice(0, SLUG_MAX_LENGTH - 5)}%`;
  const rows = db
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, pattern))
    .all();
  const held = db
    .select({ slug: organizationSlugRetirements.slug })
    .from(organizationSlugRetirements)
    .where(
      and(
        like(organizationSlugRetirements.slug, pattern),
        gt(organizationSlugRetirements.retiredAt, slugHoldCutoff(now)),
      ),
    )
    .all();
  return [...rows, ...held].map((row) => row.slug);
}
